#define TRIM_STRATEGY_NONE 0
#define TRIM_STRATEGY_MAXLEN 1
#define TRIM_STRATEGY_MINID 2

/* Trim the stream 's' according to args->trim_strategy, and return the
 * number of elements removed from the stream. The 'approx' option, if non-zero,
 * specifies that the trimming must be performed in a approximated way in
 * order to maximize performances. This means that the stream may contain
 * entries with IDs < 'id' in case of MINID (or more elements than 'maxlen'
 * in case of MAXLEN), and elements are only removed if we can remove
 * a *whole* node of the radix tree. The elements are removed from the head
 * of the stream (older elements).
 *
 * The function may return zero if:
 *
 * 1) The minimal entry ID of the stream is already < 'id' (MINID); or
 * 2) The stream is already shorter or equal to the specified max length (MAXLEN); or
 * 3) The 'approx' option is true and the head node did not have enough elements
 *    to be deleted.
 *
 * args->limit is the maximum number of entries to delete. The purpose is to
 * prevent this function from taking to long.
 * If 'limit' is 0 then we do not limit the number of deleted entries.
 * Much like the 'approx', if 'limit' is smaller than the number of entries
 * that should be trimmed, there is a chance we will still have entries with
 * IDs < 'id' (or number of elements >= maxlen in case of MAXLEN).
 */
int64_t streamTrim(stream *s, streamAddTrimArgs *args) {
    size_t maxlen = args->maxlen;
    streamID *id = &args->minid;
    int approx = args->approx_trim;
    int64_t limit = args->limit;
    int trim_strategy = args->trim_strategy;
    int64_t deleted = 0;

    if (trim_strategy == TRIM_STRATEGY_NONE)
        return 0;

    raxIterator ri;
    raxStart(&ri,s->rax);
    raxSeek(&ri,"^",NULL,0);

    while (raxNext(&ri)) {
        if (trim_strategy == TRIM_STRATEGY_MAXLEN && s->length <= maxlen)
            break;

        unsigned char *lp = ri.data, *p = lpFirst(lp);
        int64_t entries = 0;
        int64_t parsed = 0;
        unsigned char *encoded = lpGet(p, &parsed, NULL);
        if (encoded == NULL) {
            entries = parsed;
        } else {
            const char *numptr = (const char *)encoded;
            size_t numlen = (size_t)parsed;
            size_t consumed = 0;
            int negative = 0;
            unsigned long long acc = 0;
            int parsed_ok = 0;

            if (consumed == numlen) {
                parsed_ok = 0;
            } else if (numlen == 1 && numptr[0] == '0') {
                acc = 0;
                parsed_ok = 1;
                entries = 0;
            } else {
                if (numptr[0] == '-') {
                    negative = 1;
                    numptr++;
                    consumed++;
                    if (consumed == numlen) {
                        parsed_ok = 0;
                        negative = 0;
                    }
                }

                if (consumed < numlen && numptr[0] >= '1' && numptr[0] <= '9') {
                    acc = (unsigned long long)(numptr[0] - '0');
                    numptr++;
                    consumed++;
                    parsed_ok = 1;

                    while (consumed < numlen && numptr[0] >= '0' && numptr[0] <= '9') {
                        if (acc > (ULLONG_MAX / 10)) {
                            parsed_ok = 0;
                            break;
                        }
                        acc *= 10;
                        if (acc > (ULLONG_MAX - (unsigned long long)(numptr[0] - '0'))) {
                            parsed_ok = 0;
                            break;
                        }
                        acc += (unsigned long long)(numptr[0] - '0');
                        numptr++;
                        consumed++;
                    }

                    if (parsed_ok && consumed < numlen) {
                        parsed_ok = 0;
                    }

                    if (parsed_ok) {
                        if (negative) {
                            if (acc > ((unsigned long long)(-(LLONG_MIN+1))+1)) {
                                parsed_ok = 0;
                            } else {
                                entries = (int64_t)(-(long long)acc);
                            }
                        } else {
                            if (acc > (unsigned long long)LLONG_MAX) {
                                parsed_ok = 0;
                            } else {
                                entries = (int64_t)acc;
                            }
                        }
                    }
                } else if (consumed < numlen) {
                    parsed_ok = 0;
                }
            }

            if (!parsed_ok)
                serverAssert(parsed_ok != 0);
        }

        if (limit && (deleted + entries) > limit)
            break;

        int remove_node = 0;
        streamID master_id = {0};
        if (trim_strategy == TRIM_STRATEGY_MAXLEN) {
            remove_node = s->length - entries >= maxlen;
        } else {
            uint64_t encoded_id[2];
            memcpy(encoded_id, ri.key, sizeof(encoded_id));
            master_id.ms = ntohu64(encoded_id[0]);
            master_id.seq = ntohu64(encoded_id[1]);

            streamID last_id = master_id;
            int have_last = 0;
            size_t lp_bytes = lpBytes(lp);
            unsigned char *edge = lp + lp_bytes - 1;
            edge = lpPrev(lp, edge);
            if (edge != NULL) {
                int64_t lp_count = 0;
                int64_t edge_parsed = 0;
                unsigned char *edge_enc = lpGet(edge, &edge_parsed, NULL);
                if (edge_enc == NULL) {
                    lp_count = edge_parsed;
                } else {
                    long long edge_ll = 0;
                    int edge_ok = string2ll((char *)edge_enc, (size_t)edge_parsed, &edge_ll);
                    serverAssert(edge_ok != 0);
                    lp_count = (int64_t)edge_ll;
                }

                if (lp_count != 0) {
                    int64_t steps = lp_count;
                    while (steps--) {
                        edge = lpPrev(lp, edge);
                    }

                    if (edge != NULL) {
                        edge = lpNext(lp, edge);
                        if (edge != NULL) {
                            int64_t ms_off = 0;
                            int64_t seq_off = 0;
                            int64_t off_parsed = 0;
                            unsigned char *off_enc = lpGet(edge, &off_parsed, NULL);
                            if (off_enc == NULL) {
                                ms_off = off_parsed;
                            } else {
                                long long off_ll = 0;
                                int off_ok = string2ll((char *)off_enc, (size_t)off_parsed, &off_ll);
                                serverAssert(off_ok != 0);
                                ms_off = (int64_t)off_ll;
                            }

                            edge = lpNext(lp, edge);
                            if (edge != NULL) {
                                off_parsed = 0;
                                off_enc = lpGet(edge, &off_parsed, NULL);
                                if (off_enc == NULL) {
                                    seq_off = off_parsed;
                                } else {
                                    long long off_ll = 0;
                                    int off_ok = string2ll((char *)off_enc, (size_t)off_parsed, &off_ll);
                                    serverAssert(off_ok != 0);
                                    seq_off = (int64_t)off_ll;
                                }
                                last_id.ms = master_id.ms + (uint64_t)ms_off;
                                last_id.seq = master_id.seq + (uint64_t)seq_off;
                                have_last = 1;
                            }
                        }
                    }
                }
            }

            if (have_last) {
                if (last_id.ms > id->ms) {
                    remove_node = 0;
                } else if (last_id.ms < id->ms) {
                    remove_node = 1;
                } else if (last_id.seq > id->seq) {
                    remove_node = 0;
                } else if (last_id.seq < id->seq) {
                    remove_node = 1;
                } else {
                    remove_node = 0;
                }
            }
        }

        if (remove_node) {
            lpFree(lp);
            raxRemove(s->rax,ri.key,ri.key_len,NULL);
            raxSeek(&ri,">=",ri.key,ri.key_len);
            s->length -= entries;
            deleted += entries;
            continue;
        }

        if (approx) break;

        int64_t deleted_from_lp = 0;

        p = lpNext(lp, p);
        p = lpNext(lp, p);

        int64_t master_fields_count = 0;
        parsed = 0;
        encoded = lpGet(p, &parsed, NULL);
        if (encoded == NULL) {
            master_fields_count = parsed;
        } else {
            long long fields_ll = 0;
            int fields_ok = string2ll((char *)encoded, (size_t)parsed, &fields_ll);
            serverAssert(fields_ok != 0);
            master_fields_count = (int64_t)fields_ll;
        }
        p = lpNext(lp,p);
        for (int64_t j = 0; j < master_fields_count; j++)
            p = lpNext(lp,p);
        p = lpNext(lp,p);

        while (p) {
            /* We keep a copy of p (which point to flags part) in order to
             * update it after (and if) we actually remove the entry */
            unsigned char *pcopy = p;

            int flags = lpGetInteger(p);
            p = lpNext(lp, p); /* Skip flags. */
            int to_skip;

            int ms_delta = lpGetInteger(p);
            p = lpNext(lp, p); /* Skip ID ms delta */
            int seq_delta = lpGetInteger(p);
            p = lpNext(lp, p); /* Skip ID seq delta */

            streamID currid = {0}; /* For MINID */
            if (trim_strategy == TRIM_STRATEGY_MINID) {
                currid.ms = master_id.ms + ms_delta;
                currid.seq = master_id.seq + seq_delta;
            }

            int stop;
            if (trim_strategy == TRIM_STRATEGY_MAXLEN) {
                stop = s->length <= maxlen;
            } else {
                if (currid.ms > id->ms) {
                    stop = 1;
                } else if (currid.ms < id->ms) {
                    stop = 0;
                } else if (currid.seq > id->seq) {
                    stop = 1;
                } else if (currid.seq < id->seq) {
                    stop = 0;
                } else {
                    stop = 1;
                }
            }
            if (stop)
                break;

            if (flags & STREAM_ITEM_FLAG_SAMEFIELDS) {
                to_skip = master_fields_count;
            } else {
                to_skip = lpGetInteger(p);
                p = lpNext(lp,p);
                to_skip *= 2;
            }

            while(to_skip--) p = lpNext(lp,p);
            p = lpNext(lp,p);

            if (!(flags & STREAM_ITEM_FLAG_DELETED)) {
                intptr_t delta = p - lp;
                flags |= STREAM_ITEM_FLAG_DELETED;
                lp = lpReplaceInteger(lp, &pcopy, flags);
                deleted_from_lp++;
                s->length--;
                p = lp + delta;
            }
        }
        deleted += deleted_from_lp;

        p = lpFirst(lp);
        lp = lpReplaceInteger(lp,&p,entries-deleted_from_lp);
        p = lpNext(lp,p);
        int64_t marked_deleted = 0;
        parsed = 0;
        encoded = lpGet(p, &parsed, NULL);
        if (encoded == NULL) {
            marked_deleted = parsed;
        } else {
            long long marked_ll = 0;
            int marked_ok = string2ll((char *)encoded, (size_t)parsed, &marked_ll);
            serverAssert(marked_ok != 0);
            marked_deleted = (int64_t)marked_ll;
        }
        lp = lpReplaceInteger(lp,&p,marked_deleted+deleted_from_lp);
        p = lpNext(lp,p);

        entries -= deleted_from_lp;
        marked_deleted += deleted_from_lp;
        if (entries + marked_deleted > 10 && marked_deleted > entries/2) {
            /* TODO: perform a garbage collection. */
        }

        raxInsert(s->rax,ri.key,ri.key_len,lp,NULL);

        break;
    }

    raxStop(&ri);
    return deleted;
}

/* Trims a stream by length. Returns the number of deleted items. */
int64_t streamTrimByLength(stream *s, long long maxlen, int approx) {
    streamAddTrimArgs args = {
        .trim_strategy = TRIM_STRATEGY_MAXLEN,
        .approx_trim = approx,
        .limit = approx ? 100 * server.stream_node_max_entries : 0,
        .maxlen = maxlen
    };
    return streamTrim(s, &args);
}

/* Trims a stream by minimum ID. Returns the number of deleted items. */
int64_t streamTrimByID(stream *s, streamID minid, int approx) {
    streamAddTrimArgs args = {
        .trim_strategy = TRIM_STRATEGY_MINID,
        .approx_trim = approx,
        .limit = approx ? 100 * server.stream_node_max_entries : 0,
        .minid = minid
    };
    return streamTrim(s, &args);
}

